import { APP_ROUTES } from '@/constants/app-routes';

/** Rotas que rodam no shell logado mesmo sem sessão (modo visitante do Broker 4.0). */
export const VISITOR_ROUTES = [
    APP_ROUTES.public.entrar.name,
    APP_ROUTES.public.cadastro.name,
] as const;

export const checkIsVisitorRoute = (pathname: string): boolean =>
    VISITOR_ROUTES.some((route) => pathname === route || pathname.startsWith(`${route}/`));
